#include <stdio.h>
#define MIN_AGE 1
#define MAX_AGE 120
int main(void) {
    int age;
    double fee;
    printf("Enter age (1-120): ");
    scanf("%d", &age);
    while (age < MIN_AGE || age > MAX_AGE) {
        printf("Error: age must be between 1 and 120.\n");
        printf("Enter age (1-120): ");
        scanf("%d", &age);
    }
    if (age < 13)
        fee = 15.00;
    else if (age < 25)
        fee = 25.50;
    else if (age < 65)
        fee = 39.99;
    else
        fee = 22.75;
    printf("Monthly fee: $%.2lf\n", fee);
    return 0;
}

#include <stdio.h>
int main(void) {
    double r, min = 0, max = 0, sum = 0;
    int count = 0;
    printf("Enter readings (negative to stop):\n");
    scanf("%lf", &r);
    while (r >= 0) {
        if (count == 0 || r < min) min = r;
        if (count == 0 || r > max) max = r;
        sum += r;
        count++;
        scanf("%lf", &r);
    }
    if (count == 0) {
        printf("No readings entered.\n");
    } else {
        printf("Readings: %d\n", count);
        printf("Minimum: %.1lf\n", min);
        printf("Maximum: %.1lf\n", max);
        printf("Average: %.2lf\n", sum / count);
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int size, row, col;
    printf("Enter size (1-9): ");
    scanf("%d", &size);
    row = 1;
    while (row <= size) {
        col = 1;
        while (col <= size) {
            if (col <= row)
                printf("%d", row);
            else
                printf("*");
            col++;
        }
        printf("\n");
        row++;
    }
    return 0;
}
